public class DateHelper {
    public static boolean isLeap(int year) {
        return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    }

    public static int daysInYear(int year) {
        return isLeap(year) ? 366 : 365;
    }
}

